int max(int a, int b) { return a > b ? a : b; }

int solve(int i, int j) {
    if (i > j) return 0;
    if (i == j) return 0;
    if (dp[i][j] != -1) return dp[i][j];

    int res = 0;
    // Try all splits
    for (int k = i; k < j; k++) {
        res = max(res, solve(i, k) + solve(k+1, j));
    }
    // Try matching i with j
    if (color[i] == color[j]) {
        res = max(res, solve(i+1, j-1) + 2);
    }
    dp[i][j] = res;
    return res;
}

