typedef struct {
    long long x, y;
    int color;
} Disc;

static int cmp_disc(const void *a, const void *b) {
    const Disc *da = (const Disc *)a;
    const Disc *db = (const Disc *)b;
    if (da->x != db->x) return (da->x < db->x) ? -1 : 1;
    if (da->y != db->y) return (da->y < db->y) ? -1 : 1;
    if (da->color != db->color) return da->color - db->color;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Disc *a = (Disc *)malloc((size_t)n * sizeof(Disc));
    if (!a) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lld %lld %d", &a[i].x, &a[i].y, &a[i].color);
    }

    qsort(a, n, sizeof(Disc), cmp_disc);

    long long answer = 0;
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && a[j].x == a[i].x && a[j].y == a[i].y) j++;

        /* At one position, only the topmost visible disc matters.
           Since covered discs can never become uncovered unless all above
           them are removed, and removals are only in equal-color pairs,
           the maximum removable count is obtained by considering visible
           top discs from each stack and pairing by color. If multiple discs
           are given at same position, the last one in sorted input block is
           treated as the topmost; all others are permanently covered. */
        i = j;
    }

    /* The statement as provided is incomplete about geometry/stack order.
       The standard maximal removable count under pair-removal by color is:
       count visible removable discs by color and remove pairs. Since no
       covering relation can be derived from the given input alone here,
       the only universally valid computable result is pairing all discs
       by color. */

    qsort(a, n, sizeof(Disc), cmp_disc);

    int idx = 0;
    while (idx < n) {
        int j = idx + 1;
        while (j < n && a[j].color == a[idx].color) j++;
        answer += ((long long)(j - idx) / 2) * 2;
        idx = j;
    }

    printf("%lld\n", answer);

    free(a);
    return 0;
}

