int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }

    // For each column, track the count of each color among uncovered discs
    vector<int> top(n, 0); // tracks the row index of the topmost disc in each column
    vector<map<char, int>> colCount(m); 

    // Initialize: all discs are uncovered initially (from bottom)
    for (int col = 0; col < m; col++) {
        for (int row = n - 1; row >= 0; row--) {
            if (grid[row][col] != '.') {
                colCount[col][grid[row][col]]++;
                top[col] = row;
                break;
            }
        }
    }

    int removed = 0;
    bool changed = true;
    while (changed) {
        changed = false;
        // Try to find pairs across columns
        for (int c1 = 0; c1 < m; c1++) {
            if (top[c1] >= n) continue;
            char color = grid[top[c1]][c1];
            for (int c2 = c1 + 1; c2 < m; c2++) {
                if (top[c2] >= n) continue;
                if (grid[top[c2]][c2] == color) {
                    // Remove both
                    removed += 2;
                    // Remove from column c1
                    colCount[c1][color]--;
                    if (colCount[c1][color] == 0) colCount[c1].erase(color);
                    // Find next uncovered disc in column c1
                    int r;
                    for (r = top[c1] - 1; r >= 0; r--) {
                        if (grid[r][c1] != '.') break;
                    }
                    top[c1] = (r >= 0) ? r : n;

                    // Remove from column c2
                    colCount[c2][color]--;
                    if (colCount[c2][color] == 0) colCount[c2].erase(color);
                    for (r = top[c2] - 1; r >= 0; r--) {
                        if (grid[r][c2] != '.') break;
                    }
                    top[c2] = (r >= 0) ? r : n;

                    changed = true;
                    break;
                }
            }
            if (changed) break;
        }
    }

    cout << removed << "\n";
    return 0;
}

