double x[25], y[25], r[25];
int color[25];
int covers[25]; // bitmask: covers[i] = set of discs that cover disc i (indices j > i that overlap)

bool overlaps(int i, int j) {
    double dx = x[i]-x[j], dy = y[i]-y[j];
    return dx*dx + dy*dy < (r[i]+r[j])*(r[i]+r[j]);
}

map<int,int> memo;

int solve(int mask) {
    auto it = memo.find(mask);
    if (it != memo.end()) return it->second;

    // Find exposed discs (in mask, not covered by any other disc in mask)
    vector<int> exposed;
    for (int i = 0; i < n; i++) {
        if (!(mask & (1<<i))) continue;
        bool exp = true;
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            if (!(mask & (1<<j))) continue;
            if (j > i && overlaps(i,j)) { exp = false; break; }
        }
        if (exp) exposed.push_back(i);
    }

    int best = 0;
    for (int a = 0; a < exposed.size(); a++)
        for (int b = a+1; b < exposed.size(); b++) {
            if (color[exposed[a]] == color[exposed[b]]) {
                int newmask = mask ^ (1<<exposed[a]) ^ (1<<exposed[b]);
                best = max(best, 2 + solve(newmask));
            }
        }

    memo[mask] = best;
    return best;
}

