#include <bits/stdc++.h>
using namespace std;

/*
Interpretation:
- Each disc has a color and may cover some other discs.
- A disc is removable only if no other remaining disc is on top of it
  (i.e. it currently has indegree 0 in the "covered by" relation).
- In one move, we remove two removable discs of the same color.
- Goal: maximize number of removed discs.

Model:
- DAG from top disc -> lower disc.
- State of currently removable discs changes as discs are removed.
- We use DP over subsets: for each set of already removed discs, determine
  which discs are currently removable, and try removing any pair of removable
  discs with equal color.

This is exponential and intended for small n.
Input format assumed:
n m
c1 c2 ... cn
m lines: a b   meaning disc a covers disc b
Discs are 1-indexed in input.

Output:
maximum number of removed discs
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<int> color(n);
    for (int i = 0; i < n; ++i) cin >> color[i];

    vector<int> predMask(n, 0); // discs above this disc
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        predMask[b] |= (1 << a);
    }

    int N = 1 << n;
    vector<char> dp(N, 0);
    dp[0] = 1;

    int ans = 0;

    for (int mask = 0; mask < N; ++mask) {
        if (!dp[mask]) continue;

        int removed = __builtin_popcount((unsigned)mask);
        ans = max(ans, removed);

        vector<int> freeDiscs;
        for (int i = 0; i < n; ++i) {
            if ((mask & (1 << i)) == 0) {
                // removable if all discs above it are already removed
                if ((predMask[i] & ~mask) == 0) {
                    freeDiscs.push_back(i);
                }
            }
        }

        for (int i = 0; i < (int)freeDiscs.size(); ++i) {
            for (int j = i + 1; j < (int)freeDiscs.size(); ++j) {
                int a = freeDiscs[i], b = freeDiscs[j];
                if (color[a] == color[b]) {
                    dp[mask | (1 << a) | (1 << b)] = 1;
                }
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

