from functools import lru_cache

def solve():
    input_data = sys.stdin.read().split()
    idx = 0

    # Read number of stacks
    n = int(input_data[idx]); idx += 1
    stacks = []
    for i in range(n):
        k = int(input_data[idx]); idx += 1
        stack = []
        for j in range(k):
            stack.append(input_data[idx]); idx += 1
        stacks.append(tuple(stack))

    stacks = tuple(stacks)

    @lru_cache(maxsize=None)
    def dfs(tops):
        # tops[i] = number of discs remaining in stack i
        best = 0
        # Find all pairs of stacks with same top color
        top_colors = {}
        for i, t in enumerate(tops):
            if t > 0:
                color = stacks[i][t-1]
                if color not in top_colors:
                    top_colors[color] = []
                top_colors[color].append(i)

        for color, indices in top_colors.items():
            if len(indices) >= 2:
                # Try all pairs
