public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        // Read discs: for each column (x), store a stack of colors from bottom to top.
        // We'll store as ArrayList and track index of top.
        Map<Integer, ArrayList<Integer>> columns = new HashMap<>();
        // Also track max x
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            int c = Integer.parseInt(parts[2]);
            columns.computeIfAbsent(x, k -> new ArrayList<>());
            // We'll add later sorted by y; since input may not be sorted by y, we need to sort per column.
            // Better: store all and sort later.
            columns.get(x).add(c); // We'll sort later
        }

        // For each column, sort by y? Actually we don't have y stored here. We need to keep y.
        // Let's re-read with y.
        // Better approach: store triples and sort by y after reading all.
        List<int[]> discs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            int c = Integer.parseInt(parts[2]);
            discs.add(new int[]{x, y, c});
        }

        // Group by x, sort each by y ascending
        Map<Integer, List<int[]>> byX = new HashMap<>();
        for (int[] d : discs) {
            byX.computeIfAbsent(d[0], k -> new ArrayList<>()).add(d);
        }

        // For each column, sort by y and build stack of colors
        Map<Integer, int[]> stacks = new HashMap<>(); // stack as array of colors
        Map<Integer, Integer> topIdx = new HashMap<>(); // current top index (0 = bottom)

        for (int x : byX.keySet()) {
            List<int[]> list = byX.get(x);
            list.sort(Comparator.comparingInt(a -> a[1]));
            int[] arr = new int[list.size()];
            for (int i = 0; i < list.size(); i++) {
                arr[i] = list.get(i)[2];
            }
            stacks.put(x, arr);
            topIdx.put(x, arr.length - 1); // top is last element (largest y)
        }

        // Map from color to set of columns where that color is on top
        Map<Integer, TreeSet<Integer>> colorToCols = new HashMap<>();
        for (int x : stacks.keySet()) {
            int[] arr = stacks.get(x);
            if (arr.length > 0) {
                int topColor = arr[topIdx.get(x)];
                colorToCols.computeIfAbsent(topColor, k -> new TreeSet<>()).add(x);
            }
        }

        int removed = 0;
        boolean changed = true;
        while (changed) {
            changed = false;
            // Look for a color with at least 2 columns
            for (int color : new ArrayList<>(colorToCols.keySet())) {
                TreeSet<Integer> cols = colorToCols.get(color);
                while (cols.size() >= 2) {
                    changed = true;
                    // Remove two columns (could be any two; take first two)
                    int c1 = cols.pollFirst();
                    int c2 = cols.pollFirst();
                    removed += 2;

                    // Update stack for c1
                    int idx1 = topIdx.get(c1);
                    idx1--;
                    topIdx.put(c1, idx1);
                    if (idx1 >= 0) {
                        int newColor = stacks.get(c1)[idx1];
                        colorToCols.computeIfAbsent(newColor, k -> new TreeSet<>()).add(c1);
                    }

                    // Update stack for c2
                    int idx2 = topIdx.get(c2);
                    idx2--;
                    topIdx.put(c2, idx2);
                    if (idx2 >= 0) {
                        int newColor = stacks.get(c2)[idx2];
                        colorToCols.computeIfAbsent(newColor, k -> new TreeSet<>()).add(c2);
                    }
                }
                if (cols.isEmpty()) {
                    colorToCols.remove(color);
                }
            }
        }

        System.out.println(removed);
    }
}

